package com.foodordering.gateway;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.*; import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.Value; import org.springframework.cloud.gateway.filter.*; import org.springframework.core.Ordered; import org.springframework.http.*; import org.springframework.http.server.reactive.*; import org.springframework.stereotype.Component; import org.springframework.web.server.ServerWebExchange; import reactor.core.publisher.Mono;
@Component class JwtGatewayFilter implements GlobalFilter,Ordered {private final SecretKey key;JwtGatewayFilter(@Value("${jwt.secret}")String secret){key=Keys.hmacShaKeyFor(Base64.getDecoder().decode(secret));}public int getOrder(){return -1;}public Mono<Void> filter(ServerWebExchange x,GatewayFilterChain chain){String path=x.getRequest().getPath().value();if(path.equals("/users/register")||path.equals("/auth/login")||path.startsWith("/actuator/")||path.contains("swagger"))return chain.filter(withCorrelation(x));String h=x.getRequest().getHeaders().getFirst(HttpHeaders.AUTHORIZATION);if(h==null||!h.startsWith("Bearer "))return unauthorized(x);try{Claims c=Jwts.parser().verifyWith(key).build().parseSignedClaims(h.substring(7)).getPayload();ServerHttpRequest r=withCorrelation(x).getRequest().mutate().header("X-User-Id",String.valueOf(c.get("userId",Long.class))).header("X-User-Role",c.get("role",String.class)).build();return chain.filter(x.mutate().request(r).build());}catch(Exception e){return unauthorized(x);}}private ServerWebExchange withCorrelation(ServerWebExchange x){String c=x.getRequest().getHeaders().getFirst("X-Correlation-Id");if(c==null)c=UUID.randomUUID().toString();return x.mutate().request(x.getRequest().mutate().header("X-Correlation-Id",c).build()).build();}private Mono<Void> unauthorized(ServerWebExchange x){ServerHttpResponse r=x.getResponse();r.setStatusCode(HttpStatus.UNAUTHORIZED);r.getHeaders().setContentType(MediaType.APPLICATION_JSON);byte[] b=("{\"timestamp\":\""+Instant.now()+"\",\"status\":401,\"error\":\"Unauthorized\",\"message\":\"Authentication is required\",\"path\":\""+x.getRequest().getPath()+"\"}").getBytes(StandardCharsets.UTF_8);return r.writeWith(Mono.just(r.bufferFactory().wrap(b)));}}
